const defaultSettings={deliveryFee:25,firstOrderFree:true,promoText:"Free delivery on your first order!",morningStart:"06:00",morningEnd:"09:00",eveningStart:"18:00",eveningEnd:"20:00",logoImage:"/icons/ksr-512.png",heroImage:"",familyImage:"",primaryGreen:"#176b3a",secondaryGreen:"#2f8a50",backgroundWhite:"#ffffff",headerTitle:"KSR Dairy Foods",headerSubtitle:"FRESHNESS YOU CAN TRUST",headerBackground:"#176b3a",headerTextColor:"#ffffff",headerOpacity:82,headerBlur:18,footerSlogan:"Fresh every day. Made for your family.",morningHeadline:"Good morning — start with good milk.",eveningHeadline:"Good evening — goodness for your table.",customerCare:"Sun – Sat · 7 AM – 8 PM"};
function formatClock(value){const [h,m]=String(value||"00:00").split(":").map(Number);const ap=h>=12?"PM":"AM";return `${h%12||12}${m?`:${String(m).padStart(2,"0")}`:""} ${ap}`;}
function getDeliverySlots(settings){
  const now=new Date(); const mins=now.getHours()*60+now.getMinutes();
  const parse=v=>{const [h,m]=String(v||"00:00").split(":").map(Number);return h*60+m;};
  const ms=parse(settings.morningStart), me=parse(settings.morningEnd), es=parse(settings.eveningStart), ee=parse(settings.eveningEnd);
  const localKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  const dayLabel=now.toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short"});
  const tomorrow=new Date(now); tomorrow.setDate(tomorrow.getDate()+1); const tomorrowLabel=tomorrow.toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short"});
  const slots=[];
  if(mins<ms) slots.push({value:`${localKey(now)}|morning`,label:`Today (${dayLabel}) · Morning · ${formatClock(settings.morningStart)}–${formatClock(settings.morningEnd)}`});
  if(mins<es) slots.push({value:`${localKey(now)}|evening`,label:`Today (${dayLabel}) · Evening · ${formatClock(settings.eveningStart)}–${formatClock(settings.eveningEnd)}`});
  if(!slots.length || mins>=ee){const date=localKey(tomorrow);slots.push({value:`${date}|morning`,label:`Tomorrow (${tomorrowLabel}) · Morning · ${formatClock(settings.morningStart)}–${formatClock(settings.morningEnd)}`},{value:`${date}|evening`,label:`Tomorrow (${tomorrowLabel}) · Evening · ${formatClock(settings.eveningStart)}–${formatClock(settings.eveningEnd)}`});}
  return slots;
}
