  useEffect(()=>{const phone=checkout.phone.replace(/[^0-9]/g,"");const email=String(user?.email||checkout.email||profile.email||"").trim();if(phone.length<10&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){setServerFirstOrder(null);return;}let active=true;const timer=setTimeout(()=>api("/api/first-order",{method:"POST",body:JSON.stringify({phone,email})}).then(d=>{if(active&&typeof d.isFirstOrder==="boolean")setServerFirstOrder(d.isFirstOrder);}).catch(()=>{}),350);return()=>{active=false;clearTimeout(timer);};},[checkout.phone,checkout.email,user?.email,profile.email]);
  useEffect(()=>{const refresh=()=>api("/api/settings").then(d=>{if(d.settings)setSettings(v=>({...v,...d.settings}));}).catch(()=>{});refresh();const timer=setInterval(()=>{if(page!=="admin")refresh();},30000);return()=>clearInterval(timer);},[page]);
  useEffect(()=>{const timer=setInterval(()=>setNowTick(Date.now()),30000);return()=>clearInterval(timer);},[]);
  useEffect(()=>{document.documentElement.style.setProperty("--green",settings.primaryGreen||"#176b3a");document.documentElement.style.setProperty("--green2",settings.secondaryGreen||"#2f8a50");document.documentElement.style.setProperty("--cream",settings.backgroundWhite||"#ffffff");document.documentElement.style.setProperty("--lime","#dce8a7");document.documentElement.style.setProperty("--header-bg",settings.headerBackground||settings.primaryGreen||"#176b3a");document.documentElement.style.setProperty("--header-text",settings.headerTextColor||"#ffffff");document.documentElement.style.setProperty("--header-opacity",`${Math.max(10,Math.min(100,Number(settings.headerOpacity??82)))}%`);document.documentElement.style.setProperty("--header-blur",`${Math.max(0,Math.min(40,Number(settings.headerBlur??18)))}px`);document.title=settings.headerTitle||"KSR Dairy Foods";let link=document.querySelector('link[rel="icon"]');if(!link){link=document.createElement("link");link.rel="icon";document.head.appendChild(link);}link.href=settings.logoImage||"/icons/ksr-512.png";const appleIcon=document.querySelector('link[rel="apple-touch-icon"]');if(appleIcon)appleIcon.href=settings.logoImage||"/icons/ksr-192.png";},[settings]);
  useEffect(()=>{ const sync=()=>setPage(window.location.pathname.replace(/\/+$/,"")==="/admin"?"admin":"home");window.addEventListener("popstate",sync);if(window.location.pathname==="/admin")setPage("admin");return()=>window.removeEventListener("popstate",sync); },[]);
  useEffect(()=>{ if(page!=="admin" || !isAdmin) return; let active=true; const refresh=()=>api("/api/orders").then(d=>{if(active&&d.orders)setOrders(d.orders);}).catch(e=>notify(e.message||"Could not load server orders")); refresh(); const timer=setInterval(refresh,8000); return ()=>{active=false;clearInterval(timer);}; },[page,isAdmin]);
  useEffect(()=>{ if(!user?.email) return; let active=true; const refresh=async()=>{ try { const d=await api(`/api/orders?email=${encodeURIComponent(user.email)}`); if(!active||!d.orders) return; setOrders(old=>{ const previous=new Map(old.map(o=>[o.id,o.status])); const changed=d.orders.filter(o=>previous.has(o.id)&&previous.get(o.id)!==o.status); if(changed.length){ setNotifications(ns=>[...changed.map(o=>({id:`${o.id}-${o.status}`,orderId:o.id,status:o.status,createdAt:new Date().toISOString(),message:`Order ${o.id}: ${o.status}`})),...ns].slice(0,30)); notify(`Order update: ${changed[0].status}`); } return d.orders; }); } catch {} }; refresh(); const timer=setInterval(refresh,20000); return ()=>{active=false;clearInterval(timer);}; },[user?.email]);
  useEffect(()=>{ 
    api("/api/products").then(d=>{setProducts(Array.isArray(d.products)?d.products:[]);}).catch(()=>setProducts([]));
  },[]);
  useEffect(()=>{ if(user) setCheckout(c=>({...c,name:c.name||user.name||"",email:c.email||user.email||profile.email||"",phone:c.phone||profile.phone||"",address:c.address||profile.address||"",city:c.city||profile.city||"",pincode:c.pincode||profile.pincode||""})); },[user,profile]);
  useEffect(()=>{ if(!toast) return; const t=setTimeout(()=>setToast(""),2800); return ()=>clearTimeout(t); },[toast]);
